        <h2>🛒 Sua Sacola</h2>
        <div id="cart-items-list">
            <!-- Itens adicionados serão inseridos aqui pelo JavaScript -->
            <p style="text-align: center; color: #888;">Sua sacola está vazia.</p>
        </div>
        <hr>
        <div style="margin-top: 20px;">
