                // Adiciona o produto ao array do carrinho
                cart.push(produto);

                // Atualiza a interface
                atualizarCarrinho();

                // Dá um feedback visual rápido (opcional)
                this.textContent = 'Adicionado!';
                setTimeout(() => {
                    this.textContent = 'Adicionar à Sacola';
