        function atualizarCarrinho() {
            cartItemsList.innerHTML = ''; // Limpa a lista atual
            let total = 0;

            if (cart.length === 0) {
                cartItemsList.innerHTML = '<p style="text-align: center; color: #888;">Sua sacola está vazia.</p>';
            } else {
                cart.forEach((item, index) => {
                    const itemTotal = item.preco;
                    total += itemTotal;

                    // Cria o elemento HTML para cada item
                    const itemDiv = document.createElement('div');
                    itemDiv.style.padding = '10px 0';
                    itemDiv.style.borderBottom = '1px dotted #eee';
                    itemDiv.innerHTML = `
                        <strong>${item.nome}</strong> - R$ ${item.preco.toFixed(2)} 
                        <button data-index="${index}" style="float: right; background:none; border:none; color:red; cursor:pointer;">X</button>
                    `;
                    cartItemsList.appendChild(itemDiv);
                });

                // Adiciona funcionalidade de remover item (delegation)
                cartItemsList.querySelectorAll('button').forEach(removeBtn => {
                    removeBtn.addEventListener('click', function() {
                        const index = parseInt(this.dataset.index);
                        cart.splice(index, 1); // Remove o item do array
                        atualizarCarrinho(); // Re-renderiza
                    });
                });
            }

            // Atualiza o total e o contador
            cartTotalElement.textContent = `R$ ${total.toFixed(2)}`;
            cartCountElement.textContent = cart.length;
        }


        // 3. FUNÇÃO PARA ABRIR E FECHAR O CARRINHO
        cartButton.addEventListener('click', () => {
            cartSidebar.classList.toggle('open');
        });

