        window.addEventListener('click', (event) => {
            if (!event.target.closest('.floating-cart-icon') && !event.target.closest('#cart-sidebar')) {
                cartSidebar.classList.remove('open');
            }
        });

        // Chama a atualização inicial para garantir que o contador comece em 0
        atualizarCarrinho();

    </script>

